## SETTER ##
############
class SetFlag():
	def execute(self, ip, port, flag):
		load_state()
		self.error = -1
		self.error_msg = 'Unable to connect'
		child = pexpect.spawn(command % (ip, port))
		child.timeout = 3
		child.expect("choice:")
		self.error = 2

		self.error_msg = "Resetting service"
		reset(child)

		state.clear()
		state['ppl'] = [ ]

		self.error_msg = "About to create company"
		bank = random_word()
		uid = random_word()
		pin = random_pin()
		m = ""

		register_bank(child, 0, [bank, 2, uid, pin, m])

		self.error_msg = "Normal traffic"
		normal_connection(child)

		self.error_msg = "Setting flag"
		user_idx = random.randint(0, len(state['ppl']) - 1)
		person = state['ppl'][user_idx]

		log_in(child, user_idx, person)
		normal_user(child, user_idx, person, nosurprises=True)

		set_maiden_name(child, user_idx, person, set_m=flag)
		normal_user(child, user_idx, person)

		self.error_msg = "Normal traffic"
		normal_connection(child)

		self.error = 0
		self.error_msg = "All good!"
		self.flag_id = person[0] + "|" + person[2]
		self.cookie = person[3]

		save_state()
		quit(child)


	def result(self):
		return {'FLAG_ID' : self.flag_id,
			'COOKIE' : self.cookie,
			'ERROR' : self.error,
			'ERROR_MSG' : self.error_msg,
			}


############
## GETTER ##
############
class GetFlag():
	def execute(self, ip, port, flag_id, cookie):
		load_state()
		self.error = -1
		self.error_msg = 'Unable to connect'
		child = pexpect.spawn(command % (ip, port))
		child.timeout = 3
		child.expect("choice:")
		self.error = 2

		self.error_msg = "Normal connection 1"
		normal_connection(child)

		fb, fu = flag_id.split("|")
		idx = [ i for i,j in enumerate(state['ppl']) if j[0] == fb and j[2] == fu and j[3] == cookie ][0]

		self.error_msg = "Logging in"
		log_in(child, idx, state['ppl'][idx])
		normal_user(child, idx, state['ppl'][idx], nosurprises=True)

		self.error_msg = "set flag"
		flag = show_maiden_name(child, idx, state['ppl'][idx])

		normal_user(child, idx, state['ppl'][idx])

		self.flag = flag
		self.error = 0
		self.error_msg = "ALL GOOD!"
		save_state()
		quit(child)

	def result(self):
		return {'FLAG' : self.flag,
			'ERROR' : self.error,
			'ERROR_MSG' : self.error_msg,
			}


