class Benign():
	# randomly call this benign script about every 30 seconds
	# with standard deviation of 3.3 seconds 
	call_interval = 30  
	call_interval_sd = 3.3  

	def execute(self, ip, port):
		load_state()
		self.error = -1
		self.error_msg = 'Connection failed'
		child = pexpect.spawn(command % (ip, port))
		child.timeout = 3
		child.expect("choice:")
		self.error = 2

		self.error_msg = "Normal connection 1"
		normal_connection(child)
		self.error_msg = "Normal connection 3"
		normal_connection(child)

		self.error = 0
		self.error_msg = "All good!"
		save_state()
		quit(child)

	def result(self):
		return {'ERROR' : self.error,
			'ERROR_MSG' : self.error_msg,
			}



